// src/pages/VisitorInfo.jsx
import React, { useEffect, useState } from 'react';
import ReactDOM from 'react-dom';
import axios from 'axios';
import '../components/VisitorInfo.css';
// Individual icon imports
import { FaMapMarker } from 'react-icons/fa';
import { FaClock } from 'react-icons/fa';
import { FaInfoCircle } from 'react-icons/fa';
import { FaBullhorn } from 'react-icons/fa';
import { FaTimes } from 'react-icons/fa';
import { FaMapPin } from 'react-icons/fa';
import { FaCalendarAlt } from 'react-icons/fa';
import { FaLeaf } from 'react-icons/fa';
import { FaChevronRight } from 'react-icons/fa';

export default function GuestVisitorInfo() {
  // dummy fallback info (images live in public/)
  const dummyInfo = {
    visitingHours: `Monday – Friday: 9:00 AM – 5:00 PM
Saturday – Sunday: 10:00 AM – 4:00 PM
Holidays: 10:00 AM – 2:00 PM`,
    rules: `• Please check in at the reception area
• Maintain silence and respect for other visitors
• No outside food and drinks allowed
• Keep the premises clean
• Follow designated pathways
• Photography requires permission`,
    amenities: [
      { 
        imageUrl: '/amenity1.jpg',
        title: 'Memorial Church',
        description: 'A peaceful sanctuary for prayer and reflection'
      },
      { 
        imageUrl: '/amenity2.jpg',
        title: 'Memorial Garden',
        description: 'Beautifully landscaped gardens for quiet contemplation'
      },
      { 
        imageUrl: '/amenity3.jpg',
        title: 'Parking Area',
        description: 'Spacious parking facility with 24/7 security'
      },
      { 
        imageUrl: '/amenity4.jpg',
        title: 'Memorial Chapel',
        description: 'Intimate space for private ceremonies'
      },
      { 
        imageUrl: '/amenity5.jpg',
        title: 'Fountain Plaza',
        description: 'Serene water feature with seating areas'
      }
    ]
  };

  const [info, setInfo]                   = useState(null);
  const [announcements, setAnnouncements] = useState([]);
  const [error, setError]                 = useState('');
  const [selected, setSelected]           = useState(null);
  const [loading, setLoading]             = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        // Fetch visitor info using public endpoint for guests
        const infoResponse = await axios.get(`${process.env.REACT_APP_API_URL}/public-access/info`);
        setInfo(infoResponse.data);
      } catch (err) {
        console.error('Error fetching visitor info:', err);
        setInfo(null);
      }

      try {
        // Fetch announcements using public endpoint for guests
        const announcementsResponse = await axios.get(`${process.env.REACT_APP_API_URL}/public/announcements`);
        const sorted = announcementsResponse.data.sort((a, b) => (b.pinned === true) - (a.pinned === true));
        setAnnouncements(sorted);
        setError('');
      } catch (err) {
        console.error('Error fetching announcements:', err);
        setError('Failed to load announcements');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // pick API result if it has amenities, else dummy
  const displayInfo =
    info && Array.isArray(info.amenities) && info.amenities.length
      ? info
      : dummyInfo;

  // helper to turn "/amenityX.png" into "http://localhost:3000/amenityX.png"
  const getAmenitySrc = url => {
    if (!url) return '';
    const origin = window.location.origin;
    return url.match(/^https?:/) ? url : `${origin}${url}`;
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Date not available';
    try {
      return new Date(dateString).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
    } catch (error) {
      return 'Invalid date';
    }
  };

  if (loading) {
    return (
      <div className="visitor-loading-container">
        <div className="visitor-loading-spinner"></div>
        <p>Loading visitor information...</p>
      </div>
    );
  }

  return (
    <div className={`visitor-magazine-container ${selected ? 'visitor-blurred' : ''}`}>
      
      {/* Hero Section */}
      <section className="visitor-hero-section">
        <div className="visitor-hero-background">
          <div className="visitor-hero-overlay"></div>
        </div>
        <div className="visitor-hero-content">
          <div className="visitor-hero-badge">
            <FaLeaf className="visitor-badge-icon" />
            <span>Memorial Park</span>
          </div>
          <h1 className="visitor-hero-title">Grave Path Memorial Park</h1>
          <p className="visitor-hero-description">
            A serene sanctuary where memories live forever. Experience peace, reflection, 
            and connection in our beautifully maintained memorial grounds.
          </p>
          <div className="visitor-hero-stats">
            <div className="visitor-hero-stat">
              <span className="visitor-stat-number">{announcements.length}</span>
              <span className="visitor-stat-label">Active Announcements</span>
            </div>
            <div className="visitor-hero-stat">
              <span className="visitor-stat-number">{displayInfo.amenities.length}</span>
              <span className="visitor-stat-label">Park Amenities</span>
            </div>
          </div>
        </div>
      </section>

      {/* Content Flow */}
      <div className="visitor-content-flow">
        
        {/* Announcements Section */}
        <section className="visitor-flow-section visitor-announcements-flow">
          <div className="visitor-section-header">
            <div className="visitor-section-meta">
              <FaBullhorn className="visitor-section-icon" />
              <span className="visitor-section-category">Updates</span>
            </div>
            <h2 className="visitor-section-title">Important Announcements</h2>
            <p className="visitor-section-subtitle">Stay informed with our latest news and updates</p>
          </div>

          {error && (
            <div className="visitor-error-banner">
              <FaInfoCircle className="visitor-error-icon" />
              <span>{error}</span>
            </div>
          )}

          <div className="visitor-announcements-magazine">
            {announcements.length === 0 ? (
              <div className="visitor-empty-announcements">
                <FaBullhorn className="visitor-empty-icon" />
                <h3>No Current Announcements</h3>
                <p>We'll post important updates here when available.</p>
              </div>
            ) : (
              <>
                {announcements.slice(0, 1).map(announcement => (
                  <article 
                    key={announcement._id}
                    className={`visitor-featured-announcement ${announcement.pinned ? 'pinned' : ''}`}
                    onClick={() => setSelected(announcement)}
                  >
                    <div className="visitor-article-header">
                      {announcement.pinned && (
                        <div className="visitor-pinned-badge">
                          <FaMapPin className="visitor-pin-icon" />
                          <span>Pinned</span>
                        </div>
                      )}
                      <div className="visitor-article-meta">
                        <span className="visitor-article-date">
                          <FaCalendarAlt className="visitor-date-icon" />
                          {formatDate(announcement.createdAt)}
                        </span>
                      </div>
                    </div>
                    <h3 className="visitor-article-title">{announcement.title}</h3>
                    <p className="visitor-article-preview">
                      {announcement.message?.substring(0, 150)}...
                    </p>
                    <div className="visitor-article-footer">
                      <span className="visitor-read-more">
                        Read Full Announcement
                        <FaChevronRight className="visitor-chevron-icon" />
                      </span>
                    </div>
                  </article>
                ))}

                {announcements.length > 1 && (
                  <div className="visitor-announcements-grid">
                    {announcements.slice(1).map(announcement => (
                      <article 
                        key={announcement._id}
                        className={`visitor-announcement-card ${announcement.pinned ? 'pinned' : ''}`}
                        onClick={() => setSelected(announcement)}
                      >
                        <div className="visitor-card-header">
                          {announcement.pinned && (
                            <div className="visitor-pinned-indicator">
                              <FaMapPin className="visitor-pin-icon" />
                            </div>
                          )}
                          <span className="visitor-card-date">
                            {formatDate(announcement.createdAt)}
                          </span>
                        </div>
                        <h4 className="visitor-card-title">{announcement.title}</h4>
                        <p className="visitor-card-preview">
                          {announcement.message?.substring(0, 100)}...
                        </p>
                        <div className="visitor-card-action">
                          <span className="visitor-read-link">Read More</span>
                        </div>
                      </article>
                    ))}
                  </div>
                )}
              </>
            )}
          </div>
        </section>

        {/* Visiting Hours Section */}
        <section className="visitor-flow-section visitor-hours-flow">
          <div className="visitor-section-header">
            <div className="visitor-section-meta">
              <FaClock className="visitor-section-icon" />
              <span className="visitor-section-category">Schedule</span>
            </div>
            <h2 className="visitor-section-title">Visiting Hours</h2>
            <p className="visitor-section-subtitle">Plan your visit during our operating hours</p>
          </div>

          <div className="visitor-hours-card">
            <div className="visitor-hours-content">
              <pre className="visitor-hours-text">{displayInfo.visitingHours}</pre>
            </div>
          </div>
        </section>

        {/* Rules Section */}
        <section className="visitor-flow-section visitor-rules-flow">
          <div className="visitor-section-header">
            <div className="visitor-section-meta">
              <FaInfoCircle className="visitor-section-icon" />
              <span className="visitor-section-category">Guidelines</span>
            </div>
            <h2 className="visitor-section-title">Visitor Guidelines</h2>
            <p className="visitor-section-subtitle">Please observe these guidelines for a respectful visit</p>
          </div>

          <div className="visitor-rules-card">
            <div className="visitor-rules-content">
              <pre className="visitor-rules-text">{displayInfo.rules}</pre>
            </div>
          </div>
        </section>

        {/* Amenities Section */}
        <section className="visitor-flow-section visitor-amenities-flow">
          <div className="visitor-section-header">
            <div className="visitor-section-meta">
              <FaMapMarker className="visitor-section-icon" />
              <span className="visitor-section-category">Facilities</span>
            </div>
            <h2 className="visitor-section-title">Park Amenities</h2>
            <p className="visitor-section-subtitle">Discover the beautiful facilities available to visitors</p>
          </div>

          <div className="visitor-amenities-showcase">
            {displayInfo.amenities.map((amenity, index) => (
              <div key={index} className="visitor-amenity-card">
                <div className="visitor-amenity-image">
                  <img
                    src={getAmenitySrc(amenity.imageUrl)}
                    alt={amenity.title}
                    onError={(e) => {
                      e.target.src = '/placeholder-amenity.jpg';
                    }}
                  />
                  <div className="visitor-amenity-overlay">
                    <span className="visitor-amenity-index">{String(index + 1).padStart(2, '0')}</span>
                  </div>
                </div>
                <div className="visitor-amenity-content">
                  <h3 className="visitor-amenity-title">{amenity.title}</h3>
                  <p className="visitor-amenity-description">{amenity.description}</p>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      {/* Modal for Selected Announcement */}
      {selected && (
        <div className="visitor-modal-backdrop" onClick={() => setSelected(null)}>
          <div className="visitor-modal-content" onClick={e => e.stopPropagation()}>
            <div className="visitor-modal-header">
              <div className="visitor-modal-meta">
                {selected.pinned && (
                  <div className="visitor-modal-pinned">
                    <FaMapPin className="visitor-pin-icon" />
                    <span>Pinned Announcement</span>
                  </div>
                )}
                <span className="visitor-modal-date">
                  <FaCalendarAlt className="visitor-date-icon" />
                  {formatDate(selected.createdAt)}
                </span>
              </div>
              <button 
                className="visitor-modal-close"
                onClick={() => setSelected(null)}
              >
                <FaTimes />
              </button>
            </div>
            <h2 className="visitor-modal-title">{selected.title}</h2>
            <div className="visitor-modal-body">
              <p className="visitor-modal-text">{selected.message}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
} 