import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import './ColumbariumManagement.css';

const ColumbariumManagement = () => {
  const { token } = useContext(AuthContext);
  const [activeTab, setActiveTab] = useState('slots');
  const [slots, setSlots] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const api = (endpoint, options = {}) => {
    return fetch(`http://localhost:5000/api${endpoint}`, {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
        ...options.headers
      },
      ...options
    });
  };

  const fetchSlots = async () => {
    setLoading(true);
    try {
      const response = await api('/admin/columbarium/slots');
      if (response.ok) {
        const data = await response.json();
        setSlots(data.slots || []);
      } else {
        setError('Failed to fetch slots');
      }
    } catch (error) {
      setError('Error fetching slots');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (activeTab === 'slots') {
      fetchSlots();
    }
  }, [activeTab]);

  return (
    <div className="columbarium-management">
      <div className="page-header">
        <h1>Columbarium Management</h1>
        <p>Manage columbarium slots and reservations</p>
      </div>

      {error && (
        <div className="alert alert-error">
          {error}
          <button onClick={() => setError('')}>×</button>
        </div>
      )}

      <div className="tab-navigation">
        <button 
          className={activeTab === 'slots' ? 'active' : ''}
          onClick={() => setActiveTab('slots')}
        >
          Slots Management
        </button>
        <button 
          className={activeTab === 'reservations' ? 'active' : ''}
          onClick={() => setActiveTab('reservations')}
        >
          Reservations
        </button>
      </div>

      {activeTab === 'slots' && (
        <div className="slots-section">
          <div className="section-header">
            <h2>Columbarium Slots</h2>
          </div>

          <div className="table-container">
            <table className="slots-table">
              <thead>
                <tr>
                  <th>Slot ID</th>
                  <th>Location</th>
                  <th>Status</th>
                  <th>Price</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr><td colSpan="4" className="loading">Loading...</td></tr>
                ) : slots.length === 0 ? (
                  <tr><td colSpan="4" className="no-data">No slots found</td></tr>
                ) : (
                  slots.map(slot => (
                    <tr key={slot.slotId}>
                      <td>{slot.slotId}</td>
                      <td>Floor {slot.floor}, Section {slot.section}</td>
                      <td><span className={`status-badge ${slot.status}`}>{slot.status}</span></td>
                      <td>₱{slot.price.toLocaleString()}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default ColumbariumManagement;